// Every source to fetch for each product: its manufacturer page, document links on that page, and search results
const s = $('Find settings').first().json;
const plans = $('Pick the product page').all().map(i => i.json);
const pages = $input.all().map(i => String(i.json.html || ''));
const decode = t => { try { return decodeURIComponent(t); } catch (e) { return String(t || ''); } };
const hostOf = u => (/^https?:\/\/([^\/:?#]+)/i.exec(String(u || '')) || [])[1]?.toLowerCase().replace(/^www\./, '') || '';
