    const u = direct(url);
    if (!/^https?:\/\//i.test(u) || list.some(x => x.url === u)) return;
    list.push({ product_id: p.product_id, model: p.model, url: u, kind, label: p.vendor + ' ' + LABEL[kind] + (/\.pdf(?:$|\?)/i.test(u) ? ' (PDF)' : ''), found_via: via });
