// Keep only text that names the exact model, then trim it to the paragraphs most likely to answer questions
const s = $('Find settings').first().json;
const c = $('List the sources').item.json;
const SPEC = /\b(spec|dimension|size|weight|material|capacity|power|battery|resolution|port|speed|rating|includ|in the box|compatib|support|install|mount|storage|record|wash|clean|care|temperature|safe)/gi;
const raw = String($json.text || $json.data?.markdown || '');
