  product_url: p.onlineStoreUrl || p.onlineStorePreviewUrl || '', revision: Number(last.revision || 0) + 1,
  source_hash: sourceHash, sources: used, asked, last_status: last.status || '' };
if (!model) return [{ json: { ...base, status: 'failed', error: 'no model number' } }];
if (!used.length) return [{ json: { ...base, status: 'no_sources', error: 'no source names ' + model } }];
if (unchanged) return [{ json: { ...base, status: last.status, error: 'sources unchanged since revision ' + last.revision } }];
