// Fail closed: an answer survives only if every quote is in the source it names and every number is in its own quotes
const s = $('Draft settings').first().json;
const p = $('Build the prompt').first().json;
const r = $input.first().json;
const norm = t => String(t || '').toLowerCase().replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
  .replace(/[‐-―−]/g, '-').replace(/\*\*/g, '').replace(/\s+/g, ' ').trim();
const parse = t => { if (t && typeof t === 'object') return t; const x = String(t || '').replace(/<think>[\s\S]*?<\/think>/g, '').replace(/```(?:json)?/g, '').trim();
