  // Numbers in the answer must be in this answer's own quotes, not just somewhere in the manual
  // (the product's own title and model number don't count: "2.5G 30W" in a title isn't a claim)
  const quoted = norm(cites.map(c => c.quote).join(' ')).replace(/(\d),(?=\d{3})/g, '$1');
  let claim = a.replace(new RegExp(escRe(p.title), 'gi'), ' ');
  if (modelOk) claim = claim.replace(new RegExp(modelOk.source, 'gi'), ' ');
  const nums = [...new Set((claim.replace(/(\d),(?=\d{3})/g, '$1').match(/\d+(?:\.\d+)?/g) || []))];
  const missing = nums.filter(n => !new RegExp('(^|[^0-9.])' + escRe(n) + '(?![0-9]|\\.[0-9])').test(quoted));
  if (!reason && missing.length) reason = 'number not in its quote: ' + missing.join(', ');
  if (!reason && seen.has(norm(q))) reason = 'duplicate question';
  seen.add(norm(q));
  if (reason) rejected.push({ question: q, answer: a, reason });
  else candidates.push({ id: candidates.length, question: q, answer: a, intent: f.intent || 'other', citations: cites });
}
const error = r.error ? 'model call failed: ' + String(r.error.message || r.error).slice(0, 200) : (!d ? 'reply was not JSON' : '');
const audit = JSON.stringify({ product: { title: p.title, model: p.model }, candidates: candidates.map(({ id, question, answer, citations }) => ({ id, question, answer, quotes: citations.map(c => ({ source: c.source, quote: c.quote })) })),
  sources: p.sources.filter(x => candidates.some(c => c.citations.some(k => k.source === x.id))).map(({ id, kind, text }) => ({ id, kind, text })) });
return [{ json: { ...p, prompt: undefined, candidates, rejected, error, audit, model_used: s.model } }];

// An answer goes to review only with a clear yes on all three checks; a missing verdict is a no
const c = $('Check the quotes').first().json;
const r = $input.first().json;
const fromAudit = r.text !== undefined || r.error !== undefined || r.verdicts !== undefined;
let d = Array.isArray(r.verdicts) ? r : null; // the chain may hand back parsed JSON
if (fromAudit && !d) { const x = String(r.text || '').replace(/```(?:json)?/g, '').trim(); try { d = JSON.parse(x); } catch (e) { const m = x.match(/\{[\s\S]*\}/); try { d = m ? JSON.parse(m[0]) : null; } catch (e2) {} } }
const verdicts = (d && d.verdicts) || [];
const faqs = [], rejected = [...c.rejected];
for (const f of c.candidates) {
  const v = verdicts.filter(x => Number(x.id) === f.id);
  if (v.length === 1 && v[0].supported === true && v[0].exact_model === true && v[0].answers_question === true) faqs.push(f);
  else rejected.push({ question: f.question, answer: f.answer, reason: 'audit: ' + String((v[0] && v[0].reason) || 'no clear verdict').slice(0, 200) });
}
const error = c.error || (fromAudit && r.error ? 'audit call failed: ' + String(r.error.message || r.error).slice(0, 200) : '');
const s = $('Draft settings').first().json;
return [{ json: { ...c, audit: undefined, candidates: undefined, faqs: faqs.slice(0, s.max_faqs), rejected,
  status: error ? 'failed' : faqs.length ? 'review' : 'no_answers', error } }];

// One card per product: every answer with its quotes, what was dropped and why, Approve and Reject
const d = $json;
const s = $('Draft settings').first().json;
const esc = t => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const value = JSON.stringify({ p: d.product_id, r: d.revision });
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: ('FAQs: ' + d.title).slice(0, 150) } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: esc(d.model) + ' · ' + d.faqs.length + ' answers to review · ' + d.sources.length + ' sources · ' + esc(d.model_used) }] }
];
for (const f of d.faqs) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*' + esc(f.question) + '*\n' + esc(f.answer)).slice(0, 2900) } });
  blocks.push({ type: 'context', elements: f.citations.slice(0, 3).map(c => ({ type: 'mrkdwn', text: ('\u201C' + esc(c.quote).replace(/\s+/g, ' ').slice(0, 1800) + '\u201D \u00B7 <' + c.url + '|' + esc(c.label) + '>') })) });
}
if (d.rejected.length) {
  const counts = {};
  for (const x of d.rejected) { const k = x.reason.replace(/:.*$/, ''); counts[k] = (counts[k] || 0) + 1; }
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: ':scissors: Dropped ' + d.rejected.length + ': ' + Object.entries(counts).map(([k, n]) => k + ' (' + n + ')').join(', ') }] });
}
// Customers' questions the sources couldn't answer: say so, so you can answer them by hand
const words = t => new Set(String(t).toLowerCase().match(/[a-z0-9]{3,}/g) || []);
const answered = q => d.faqs.some(f => { const a = words(f.question), b = words(q); let n = 0; b.forEach(w => a.has(w) && n++); return n >= Math.max(2, b.size * 0.6); });
if (d.asked.length) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: (':speech_balloon: Asked by customers: ' + d.asked.map(q => esc(q) + (answered(q) ? '' : ' _(the sources don\'t answer this: reply by hand, or add the answer in Shopify)_')).join(' · ')).slice(0, 1900) }] });
const admin = 'https://' + s.store_domain + '/admin/products/' + d.product_id.split('/').pop();
blocks.push({ type: 'actions', block_id: 'faq_actions', elements: [
  { type: 'button', style: 'primary', action_id: 'faq_approve', value, text: { type: 'plain_text', text: 'Approve' } },
  { type: 'button', style: 'danger', action_id: 'faq_reject', value, text: { type: 'plain_text', text: 'Reject' } },
  { type: 'button', action_id: 'faq_link', url: admin, text: { type: 'plain_text', text: 'Product in Shopify' } }
] });
return [{ json: { ...d, card: JSON.stringify({ channel: s.review_channel, text: 'FAQs to review: ' + d.title, blocks, unfurl_links: false, unfurl_media: false }) } }];

const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
if (Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) > 300) throw new Error('Stale request');
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || ''; // no URLSearchParams in the Code node
const b = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' ')));
const base = { base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'], user: (b.user || {}).username || (b.user || {}).name || '' };
if (b.type === 'view_submission' && b.view.callback_id === 'faq_add_question') {
  const v = b.view.state.values;
  return [{ json: { ...base, action: 'submit', product: String(v.product.value.value || '').trim(), question: String(v.question.value.value || '').trim() } }];
}
const a = (b.actions || [])[0];
if (!a || !/^(faq|ask)_/.test(a.action_id) || a.action_id === 'faq_link') return []; // links need nothing
let value = {}; try { value = JSON.parse(a.value || '{}'); } catch (e) {}
return [{ json: { ...base, action: a.action_id, product_id: value.p ? 'gid://shopify/Product/' + String(value.p).split('/').pop() : '',
  revision: Number(value.r || 0), question_id: value.q || 0, trigger_id: b.trigger_id, channel: (b.channel || {}).id, ts: (b.message || {}).ts,
  blocks: (b.message || {}).blocks || [] } }];

// The same card, with the buttons swapped for who decided
const c = $('Read the click').first().json;
const ok = c.action === 'faq_approve';
const blocks = c.blocks.filter(b => b.block_id !== 'faq_actions');
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: ok ? ':white_check_mark: Approved by @' + c.user + '. Publishing now.' : ':no_entry: Rejected by @' + c.user + '. Shopify was not changed.' }] });
return [{ json: { approved: ok, product_id: c.product_id, body: JSON.stringify({ channel: c.channel, ts: c.ts, text: (ok ? 'Approved: ' : 'Rejected: ') + $('Get the set').first().json.title, blocks }) } }];

const c = $('Read the click').first().json;
const q = $('Get the question').first().json;
const note = { ask_answer: ':pencil2: @' + c.user + ' asked for an answer. Drafting now; the FAQ card follows.',
  ask_bank: ':books: @' + c.user + ' added it to the ' + q.product_type + ' question bank.', ask_ignore: ':see_no_evil: Ignored by @' + c.user + '.' }[c.action];
const blocks = c.blocks.filter(b => b.block_id !== 'ask_actions');
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: note }] });
return [{ json: { answer: c.action === 'ask_answer', product_id: q.product_id, body: JSON.stringify({ channel: c.channel, ts: c.ts, text: 'Question handled', blocks }) } }];

