// One metaobjectUpsert per answer, in one request. Handles carry the revision, so the live set is untouched until the new one is linked.
const d = $json;
const faqs = JSON.parse(d.faqs || '[]');
const num = d.product_id.split('/').pop();
const defs = [], muts = [], variables = {};
faqs.forEach((f, i) => {
  defs.push(`$h${i}: MetaobjectHandleInput!, $m${i}: MetaobjectUpsertInput!`);
  muts.push(`f${i}: metaobjectUpsert(handle: $h${i}, metaobject: $m${i}) { metaobject { id } userErrors { field message } }`);
  const c = f.citations[0] || {};
  variables['h' + i] = { type: 'product_faq', handle: `faq-${num}-r${d.revision}-${i + 1}` };
  variables['m' + i] = { fields: [{ key: 'question', value: f.question }, { key: 'answer', value: f.answer },
    { key: 'source_label', value: c.label || '' }, { key: 'source_url', value: c.url || '' }] };
});
return { json: { ...d, count: faqs.length, query: `mutation(${defs.join(', ')}) { ${muts.join(' ')} }`, variables } };

const d = $('Build the FAQ entries').item.json;
const r = $json;
const ids = [], errs = [...(r.errors || []).map(e => e.message)];
for (let i = 0; i < d.count; i++) { const f = r.data && r.data['f' + i]; if (f && f.metaobject && !(f.userErrors || []).length) ids.push(f.metaobject.id); else errs.push(...((f && f.userErrors) || [{ message: 'no reply for answer ' + (i + 1) }]).map(e => e.message)); }
return { json: { product_id: d.product_id, ids, old_ids: JSON.parse(d.published_ids || '[]'), error: errs.join('; ') } };

// Delete the previous revision's entries now the new set is live
const d = $('Check the entries').item.json;
const old = d.old_ids.filter(id => !d.ids.includes(id));
return { json: { ...d, query: old.length ? 'mutation { ' + old.map((id, i) => `d${i}: metaobjectDelete(id: ${JSON.stringify(id)}) { deletedId userErrors { message } }`).join(' ') + ' }' : '' } };

