// A model number matches as whole tokens, ignoring spaces, hyphens, plus signs and dots between them:
// "UNVR-PRO" matches "UNVR Pro" and "unvr-pro", but not "UNVR" on its own.
const escRe = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const modelRe = m => {
  const parts = String(m || '').match(/[a-z]+|\d+/gi) || [];
  if (!parts.length) return null;
  return new RegExp('(^|[^a-z0-9])' + parts.map(escRe).join('[\\s_\\-+.]*') + '(?=$|[^a-z0-9])', 'i');
};
const hashOf = t => { let h = 5381; const s = String(t || ''); for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0; return (h >>> 0).toString(16); };

// Same checks for both doors: the store's form and the Slack form
const s = $('Ask settings').first().json;
const fromStore = $('Question from the store').isExecuted && !$('Which lane?').isExecuted;
const inp = fromStore ? $('Question from the store').first().json : $('Called by this workflow').first().json;
const b = fromStore ? (inp.body || {}) : inp;
const question = String(b.question || '').replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
const email = String(b.email || '').trim();
const ip = fromStore ? String(inp.headers['cf-connecting-ip'] || inp.headers['x-forwarded-for'] || '').split(',')[0].trim() : '';
let reason = '';
if (fromStore && b.website) reason = 'bot';                                  // the hidden field: people never see it
else if (question.length < s.min_chars || question.length > s.max_chars) reason = 'length';
else if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) reason = 'email';
// The product: an ID from the store form; a URL, handle or ID from Slack
const ref = String(b.product_id || b.product || '').trim();
const id = /^\d+$/.test(ref) ? ref : (ref.match(/Product\/(\d+)/) || [])[1] || '';
const handle = id ? '' : ref.replace(/^https?:\/\/[^\/]+/i, '').replace(/^\/?(collections\/[^\/]+\/)?products\//, '').replace(/[?#].*$/, '').replace(/\/$/, '');
if (!reason && !id && !handle) reason = 'product';
return [{ json: { from_store: fromStore, question, email, id, handle, asked_by: inp.asked_by || '',
  ip_hash: ip ? hashOf(s.salt + ip) : '', reason } }];

const c = $('Check the question').first().json;
const s = $('Ask settings').first().json;
const recent = $input.all().map(i => i.json).filter(r => r.createdAt && Date.now() - new Date(r.createdAt).getTime() < 36e5).length;
return [{ json: { ...c, reason: c.reason || (c.ip_hash && recent >= s.max_per_hour ? 'too many' : '') } }];

